    events_total = 0
    issues_total = 0

    for case in v['cases']:
        keys(case, 'nodes edges commodities workers quorum max_lag relax rho mode events')
        n = case['nodes']
        integer(n, 2, 32)

        edges = case['edges']
        sequence(edges, 1, 64)
        pairs = set()
        for edge in edges:
            sequence(edge, 3, 3)
            u, w, cap = edge
            integer(u, 0, n - 1)
            integer(w, 0, n - 1)
