            integer(t, 0, n - 1)
            if s == t:
                bad()
            integer(com['demand'], 0, 1000)
            sequence(com['paths'], 0, 8)
            slot_total += len(com['paths'])
            for p in com['paths']:
                path_ok(p, s, t, edges)
            distinct(com['paths'])
