            elif op == 'issue':
                keys(ev, 'op id worker')
                integer(ev['id'], 0, 10 ** 9)
                integer(ev['worker'], 0, len(workers) - 1)
                if ev['id'] in tickets:
                    bad()
                tickets.add(ev['id'])
                issues_total += 1
                if issues_total > 48:
                    bad()

            elif op == 'deliver':
                keys(ev, 'op id')
                integer(ev['id'], 0, 10 ** 9)
                if ev['id'] not in tickets:
                    bad()

            elif op == 'retune':
                keys(ev, 'op rho')
                integer(ev['rho'], 1, 8)

            elif op == 'save':
                keys(ev, 'op name')
                integer(ev['name'], 0, 10 ** 9)
                if ev['name'] in saves:
                    bad()
                saves[ev['name']] = [list(group) for group in slots]

            elif op == 'restore':
                keys(ev, 'op name')
                integer(ev['name'], 0, 10 ** 9)
                if ev['name'] not in saves:
                    bad()
                slots = [list(group) for group in saves[ev['name']]]

            elif op in ('step', 'audit'):
                keys(ev, 'op')

            else:
                bad()

    return v
